#!/usr/bin/env python3
"""Korean handoff text and self-contained HTML from measured results."""
import base64,csv,html,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'outputs/posetrack-time-study-20261106';D=O/'report'
def load(p):return json.loads(p.read_text())
def table(headers,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in rr)+'</tr>' for rr in rows)+'</table>'
def image(name,caption):
 p=O/'visualizations'/name;mime='image/png' if p.suffix=='.png' else 'image/jpeg'
 return '<figure><img src="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'"><figcaption>'+caption+'</figcaption></figure>'
def main():
 D.mkdir(exist_ok=True);s=load(O/'summary/experiment_summary.json');m={r['config']:r for r in s['metrics']};time=s['timestamp'];loss=s['original_5s_losses']['disjoint_terminal_reasons'];geo=s['geometry'];pages=[]
 def page(title,body):pages.append('<section><div class="eyebrow">PoseTrack × SCOUT · 2026.11.06 · '+str(len(pages)+1)+'/6</div><h1>'+title+'</h1>'+body+'</section>')
 names={'original_shared':'기존 C · 같은 GT 범위','B_timestamp':'시간 정렬 + Ground 제외','C_timestamp':'시간 정렬 + Mesh','C_height_abstain':'시간 정렬 + 높이 판정 유보'}
 rows=[[names[k],f"{100*m[k]['HOTA_2D']:.2f}",f"{100*m[k]['AssA_2D']:.2f}",f"{100*m[k]['IDF1_view_aware']:.2f}",m[k]['IDSW_2D'],f"{m[k]['output_rows']:,}",m[k]['global_ids']] for k in names]
 page('30초 재실행 결과와 최종 권장 설정','''<p class="lead">기존 환경과 신경망 입력을 재사용해 시간 정렬 후 30초 Tracking을 다시 실행했다. 최종 권장 결과는 <b>C_timestamp(시간 정렬 + Mesh)</b>이다.</p><p>추가 높이 처리 후보는 실제 실행·평가했지만 전체 지표가 낮아져 채택하지 않았다. 목표 점수에 맞춰 임계값을 조정하지 않았다.</p>'''+table(['실험','HOTA','AssA','Global IDF1','IDSW','출력','ID 수'],rows)+'''
 <p class="small">HOTA·AssA는 카메라별 2D 합산, Global IDF1은 공유 ID를 사용하는 별도 view-aware 지표. IDSW는 카메라별 시간축 합계. 비율 지표는 0~100. DetA·2D IDF1·ID Precision/Recall·카메라별 지표는 동봉 CSV/JSON에 포함한다.</p>
 <h2>비교 범위를 통일했다</h2><p>모든 주 비교는 동일한 36,289개 입력 관측, 2,359개 유효 카메라·시간 슬롯, GT 51,500행을 사용한다. 기존 30초 출력도 이 범위에 투영했다. 기존 전체 번호 구간의 52,713개 GT로 계산한 Global IDF1 46.64와 새 결과를 바로 비교하면 시간 정렬 효과와 평가 범위 변화가 섞인다.</p>
 <div class="callout">시간 정렬만으로 정확도가 뚜렷하게 향상되지는 않았다. 같은 GT 범위에서 Global IDF1은 47.10→47.18, HOTA는 44.20→44.05, IDSW는 294→308이다. 메타데이터 오류 대응과 성능 개선을 구분한다.</div>
 <h2>실제 실행 상태</h2><p>Ground 제외·Mesh·높이 판정 유보의 세 실험 모두 300프레임을 처리하고 결과 저장 및 GT 평가를 완료했다. 기존 소스 저장소는 보존했다. 최초 실행의 대용량 JSON 직렬화 중 exit 137을 기록해, 계산식 변경 없이 로그를 레코드 단위로 저장하도록 수정 후 재실행했다.</p>''')
 page('Timestamp: 반복 영상을 새 관측으로 쓰지 않기',table(['항목','수정 전','수정 후 (사용 가능한 카메라)'],[
 ['최대 시간 차이',f"{time['before']['max']*1000:.1f} ms",f"{time['after']['max']*1000:.1f} ms"],
 ['평균 시간 차이',f"{time['before']['mean']*1000:.2f} ms",f"{time['after']['mean']*1000:.2f} ms"],
 ['95백분위',f"{time['before']['p95']*1000:.2f} ms",f"{time['after']['p95']*1000:.2f} ms"],['50ms 초과 시점',29,0]])+
 image('timestamp_before_after.png','단순 source frame 정렬과 공통 시간축 대응 후의 관측 시각 차이.')+'''
 <p>보정 파일의 view_id로 카메라를 연결했다. cam_0→cvlabrpi10, cam_1→21, cam_2→13, cam_3→12, cam_4→7, cam_5→19, cam_6→24, cam_7→5이다. cam 번호에 1을 더해 timestamp key를 만들면 안 된다.</p>
 <p>cam_0 11개, cam_3 25개, cam_4 2개 프레임에서 timestamp와 JPEG 바이트가 동일하게 반복됐다. 프레임 500~501 부근과 550~576 부근의 큰 차이는 이러한 정지·도약을 포함한다. 파일 번호를 임의로 이동시키지 않고 제공 timestamp를 그대로 사용했다.</p>
 <p>시작 프레임의 카메라 timestamp 중앙값을 원점으로 0.1초 간격 300개 시점을 만들었다. 각 카메라의 유일한 관측 중 ±25ms 내 가장 가까운 한 장만 선택했다. 반복 38장, 시간 허용 범위 밖 1장, 동일 슬롯 충돌 1장, 구간 밖 1장을 제외했다. 총 41개 카메라·시간 슬롯은 누락으로 남긴다.</p>
 <p class="small">271개 시점은 8대 모두 관측되고, 나머지는 최소 6대가 관측된다. 최대 35ms는 유효 관측끼리의 값이며 누락 구간을 복원했다는 뜻이 아니다. timestamp는 데이터셋 초 단위 값으로 사용했고 절대 기준시각/장치 동기화를 독립 검증하지 않았다. 각 source frame의 선택·제외 사유는 frame_mapping_all_sources.csv에 있다.</p>''')
 page('Mesh 실패와 출력 누락은 별개 문제',table(['카메라','기존 30초 입력','BBox Mesh 실패','실패했지만 발목 교차 가능'],[[f"cam_{r['camera']}",r['input'],r['bbox_failures'],r['bbox_failed_ankle_available']] for r in geo['per_camera']])+'''
 <p>기존 30초 BBox 광선의 실패 2,059건은 모두 Mesh의 전체 경계 상자를 지나지만 표면 삼각형과 만나지 않는다. 이것만으로 실제 원인이 Mesh 구멍, 가려짐, 박스 하단 위치, 보정 오차 중 무엇인지 확정할 수 없다. 실제로 Mesh를 확장하거나 임의 지면 좌표를 생성하지 않았다.</p>'''+table(['기존 5초 미출력의 직접 종료 원인','관측 수'],[
 ['초기화 후보 전체가 신뢰도 조건 불통과',903],['신뢰도 통과 후보의 주요 포즈 조건 불통과',174],['기존 트랙 IoU 제한',102],['신규 Target 확인 대기',86],['높이 보정으로 카메라 관측 제거',33],['검출 간 겹침 조건',6],['합계',1304]])+'''
 <p class="small">한 관측에 하나의 직접 원인을 배정했다. 여러 조건이 동시에 실패하면 원본 AND 조건 순서로 최초 차단 단계를 표시하고 세부 플래그를 보존했다. Hungarian 실패 후 초기화로 복구될 수 있으므로 두 단계를 중복 집계하지 않았다. 정상적인 초기 확인 대기와 신뢰도 필터를 오류로 단정하지 않는다.</p>
 <h2>높이 판정 유보 후보: 채택하지 않음</h2><p>기존에는 유한한 삼각측량 좌표라도 지면 높이를 찾지 못하면 높이 오류로 처리했다(원본 30초 113회). 이 경우만 판정을 유보한 후보는 새 실험의 높이 제거 관측을 108→51건으로 줄였지만, 총 출력은 29,226→29,161행, Global IDF1은 47.18→46.60으로 낮아졌다. 다른 연결·초기화까지 연쇄적으로 바뀌기 때문에 개별 제거 감소가 전체 성능 향상을 뜻하지 않는다.</p>''')
 page('Global ID 28·38의 실제 매칭 근거',table(['사례','당시 계산값','수락 경로'],[
 ['ID 28 / cam_3 / frame 294','Ab 0.32348, Aepi 0, Ah −1.47217, As 0.01574, w=1, 최종 0.21196','GT 500 이력에서 GT 1376 대응 관측으로 연결. Hungarian 선택 후 점수 >0이라 수락.'],
 ['ID 38 / cam_7 / frame 297','Ab 0.36869, Aepi=Ah=As=0, w=1e−5, 최종 1.84345','GT 473 이력에서 GT 1391 대응 관측으로 연결. 당시 IoU=1, 낮은 검출 점수로 Re-ID 비활성.']])+'''
 <p>원본 점수는 (Aepi+5Ab+Ah+5As·w)/(1+w)에 norm 보정을 적용한다. ID 28은 음수 지면 점수가 있어도 BBox 항과 보정으로 최종 점수가 양수가 됐다. ID 38은 그 시점에 Geometry·Re-ID의 유효 기여 없이 BBox 항으로 연결됐다.</p>
 <p class="small">위 시점은 초기 GT 합의와 처음 충돌한 <b>사후 IoU≥0.5 대응 시점</b>이다. GT와 BBox 매칭에도 불확실성이 있어 최초의 실제 신원 오류라고 단정하지 않는다. ID 38의 GT 456 대응은 이후에도 기록된다. 정상 연결·혼합의 전체 이력, 후보 행렬, 상태·Bank 이벤트와 실제 특징을 동봉했다.</p>'''+image('id28_first_conflict.jpg','ID 28: 이전 일치 관측과 최초 사후 충돌. 빨강은 예측/검출, 초록은 매칭된 GT.')+image('id38_first_conflict.jpg','ID 38: 같은 예측 ID가 다른 GT와 대응한 사례. 예측 ID와 GT ID를 구분해 표시.'))
 page('Missing 복구와 Mesh 기여의 해석','''<h2>원본 30초의 재활성화 14회</h2><p>새 Target이 아직 Unconfirmed이면 복구 직후 최종 출력에 나타나지 않을 수 있다. 따라서 출력 CSV만 보지 않고 실제 재활성화 입력 관측까지 GT와 대조했다.</p>
 <p>14회 중 과거 주석 이력과 새 관측의 GT가 충돌한 사례 1회, 근거 부족으로 판정하지 못한 사례 13회다. ID 34는 과거 GT 3988 이력 이후 frame 464의 GT 437 관측을 cosine 0.54009&gt;0.5로 받아들였다. 과거 마지막 GT 지지는 frame 317로 147프레임 차이가 있으며, 바로 직전 출력에는 유효 GT 대응이 없었다. 따라서 전체 14회의 실제 복구 정확도를 0% 또는 1회 기준 비율로 제시하지 않는다.</p>
 <p>이 복구 함수는 Feature Bank 최대 cosine으로 결정하며 Geometry/Hungarian 검증을 수락 조건으로 사용하지 않는다. 기존 정상 기능을 끄거나 GT에 맞춘 새로운 거리 조건을 넣지는 않았다. 검증된 정상 복구 이미지가 없으므로 정상 사례를 만들어 넣지 않았다.</p>'''+image('missing_reactivation_conflict_0.jpg','과거 GT 지지가 있는 ID 34와 재활성화 입력의 GT 충돌. 현재 GT와 과거 GT 간 시간 간격을 함께 해석해야 한다.')+'''
 <h2>IDSW 감소가 출력량 감소 때문인가?</h2><p>Ground 제외와 Mesh 결과의 출력량은 31,159→29,226행으로 약 6.2% 감소했고 IDSW는 607→308이다. 두 결과에 공통으로 존재하는 28,169개 관측만 남긴 보조 평가에서도 IDSW가 524→290, Global IDF1이 39.83→46.66으로 달라졌다. 이 구간의 차이는 출력량 차이만으로 설명되지 않는다. 다만 공통 출력 교집합은 사후 선택한 진단 집합이며 정식 전체 결과를 대체하지 않는다.</p>''')
 page('공통 평가 형식·재현·남은 과제','''<p><code>02_tracking_results/final_recommended_30s.csv</code>가 다음 비교에 사용할 권장 결과다. source frame, 원본 timestamp, 공통 시간 index, 원본 영상 BBox, Global ID, confidence, 모델명, 설정 ID를 포함한다. Local ID는 원본이 별도 제공하지 않아 공란이다.</p>
 <h2>공통 평가 조건</h2><ul><li>Sequence 1, cam_0~7, 300개 공통 시간 시점, 같은 frame_mapping과 GT.</li><li>원본 왜곡 영상의 xywh BBox. 왜곡 보정 BBox를 GT와 섞지 않는다.</li><li>영상 자체가 없는 슬롯은 GT를 만들어 넣지 않는다. 영상이 있으나 검출·출력이 없는 경우에는 GT를 유지해 FN으로 평가한다.</li><li>TrackEval HOTA IoU 0.05~0.95 평균, Identity/CLEAR IoU 0.5. 카메라별 2D와 공유 ID 프로토콜을 분리한다.</li><li>각 시스템 전체 파이프라인 비교와 공통 Detection/Re-ID를 쓰는 Association 비교는 별도로 표시한다. 이번에는 PoseTrack 입력 고정 ablation만 수행했다.</li></ul>
 <h2>재현과 검증</h2><p>기존 scout-mtmc/posetrack-all:ba727e6 이미지, CPU 3개·RAM 16GiB 제한으로 추적했다. 새 학습·가중치 다운로드·신경망 재추론은 하지 않았다. 임계값 숫자는 유지했다. 원본 저장소 대신 별도 런너와 패치를 사용한다.</p>
 <pre>bash scripts/replay-posetrack-time-study.sh mesh NEW_OUTPUT
bash scripts/replay-posetrack-time-study.sh ground-off NEW_OUTPUT
bash scripts/replay-posetrack-time-study.sh height-abstain NEW_OUTPUT</pre>
 <p>입력 특징·좌표·점수의 정확한 재사용, 원본 5초 4,265행 동일성, 저장 방식 수정 전후 300프레임 출력 수 동일성을 확인했다. 모든 최종 Affinity pair 수식을 재계산했다. 공통 CSV 변환기는 실제 29,226행 왕복 검증과 잘못된 좌표계·ID 범위·timestamp 거절 검증을 통과했다.</p>
 <h2>전달 범위와 미완료 항목</h2><p>ZIP은 성능표·최종 CSV·GT·핵심 로그·행렬·특징·시각화·코드·실행 안내를 포함한다. 대용량 전체 로그는 서버 원본 경로와 해시를 제공한다. 데이터셋 전체·가중치·Docker 이미지·전체 신경망 특징 캐시는 제외한다. 이 ZIP만으로 결과 검토와 공통 CSV 평가는 가능하며, Tracking 재실행에는 기존 캐시와 환경이 필요하다.</p>
 <p class="small">World 미확정 좌표와 ID 혼합은 남아 있다. 독립적인 물리 보정, Mesh 복구, 60초·4개 시스템 전체 실행은 이번에 수행하지 않았다. Global IDF1≥50·AssA≥60의 목표는 달성하지 못했다. 공식 SCOUT 3D benchmark 성능으로 해석하지 않는다.</p>''')
 css='''@page{size:A4;margin:13mm 13mm}body{font-family:"Noto Sans CJK KR",sans-serif;font-size:9.5pt;line-height:1.58;color:#1d2d3a;margin:0}section{break-after:page}section:last-child{break-after:auto}.eyebrow{font-size:8pt;color:#557187;border-bottom:2px solid #28627c;padding-bottom:6px}h1{font-size:20pt;line-height:1.3;color:#163f59;margin:15px 0}h2{font-size:11.5pt;margin:15px 0 5px;color:#245d79}p{margin:9px 0}.lead{font-size:11.5pt}table{border-collapse:collapse;width:100%;font-size:8.4pt;line-height:1.45;margin:10px 0}th,td{padding:7px 6px;border-bottom:1px solid #d0dce4;text-align:left;vertical-align:top}th{background:#245b75;color:white}tr:nth-child(odd){background:#f1f5f7}.callout{background:#eaf4f8;border-left:4px solid #407d99;padding:10px}.small,figcaption{font-size:8pt;color:#506273}figure{margin:10px 0}figure img{width:100%;max-height:58mm;object-fit:contain}pre{background:#f1f4f6;padding:10px;font-size:8pt;white-space:pre-wrap}code{font-size:8pt;overflow-wrap:anywhere}li{margin:4px 0}'''
